import React, { useState, useRef } from 'react';
import { useSettings } from '../contexts/SettingsContext';

interface TabButtonProps {
  id: string;
  label: string;
  icon: string;
  isActive: boolean;
  onClick: () => void;
}

const TabButton: React.FC<TabButtonProps> = ({ id, label, icon, isActive, onClick }) => (
  <button
    onClick={onClick}
    className={`flex items-center px-4 py-3 rounded-lg font-medium transition-all duration-300 ${
      isActive
        ? 'bg-primary-600 text-white shadow-lg transform scale-105'
        : 'text-secondary-600 hover:text-primary-600 hover:bg-primary-50 hover:scale-102'
    }`}
  >
    <span className="text-lg mr-3">{icon}</span>
    <span className="hidden sm:block">{label}</span>
  </button>
);

interface SettingCardProps {
  title: string;
  description?: string;
  children: React.ReactNode;
  className?: string;
}

const SettingCard: React.FC<SettingCardProps> = ({ title, description, children, className = '' }) => (
  <div className={`bg-white rounded-xl shadow-sm border border-secondary-100 p-6 hover:shadow-md transition-all duration-300 ${className}`}>
    <div className="mb-4">
      <h3 className="text-lg font-semibold text-secondary-900 mb-1">{title}</h3>
      {description && <p className="text-sm text-secondary-500">{description}</p>}
    </div>
    {children}
  </div>
);

interface ModernInputProps {
  label: string;
  value: string | number;
  onChange: (value: string | number) => void;
  type?: 'text' | 'number' | 'url';
  placeholder?: string;
  min?: number;
  max?: number;
  icon?: string;
}

const ModernInput: React.FC<ModernInputProps> = ({ label, value, onChange, type = 'text', placeholder, min, max, icon }) => (
  <div className="space-y-2">
    <label className="block text-sm font-medium text-secondary-700">{label}</label>
    <div className="relative">
      {icon && (
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <span className="text-secondary-400 text-sm">{icon}</span>
        </div>
      )}
      <input
        type={type}
        value={value}
        onChange={(e) => onChange(type === 'number' ? Number(e.target.value) : e.target.value)}
        placeholder={placeholder}
        min={min}
        max={max}
        className={`block w-full rounded-lg border-secondary-200 shadow-sm focus:border-primary-500 focus:ring-primary-500 transition-all duration-200 ${
          icon ? 'pl-10' : 'pl-4'
        } pr-4 py-3`}
      />
    </div>
  </div>
);

interface ModernSelectProps {
  label: string;
  value: string;
  onChange: (value: string) => void;
  options: { value: string; label: string }[];
  icon?: string;
}

const ModernSelect: React.FC<ModernSelectProps> = ({ label, value, onChange, options, icon }) => (
  <div className="space-y-2">
    <label className="block text-sm font-medium text-secondary-700">{label}</label>
    <div className="relative">
      {icon && (
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <span className="text-secondary-400 text-sm">{icon}</span>
        </div>
      )}
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className={`block w-full rounded-lg border-secondary-200 shadow-sm focus:border-primary-500 focus:ring-primary-500 transition-all duration-200 ${
          icon ? 'pl-10' : 'pl-4'
        } pr-10 py-3`}
      >
        {options.map(option => (
          <option key={option.value} value={option.value}>{option.label}</option>
        ))}
      </select>
    </div>
  </div>
);

interface ModernToggleProps {
  label: string;
  description?: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
  size?: 'sm' | 'md' | 'lg';
}

const ModernToggle: React.FC<ModernToggleProps> = ({ label, description, checked, onChange, size = 'md' }) => {
  const sizeClasses = {
    sm: 'h-5 w-9',
    md: 'h-6 w-11',
    lg: 'h-7 w-13'
  };

  const dotSizeClasses = {
    sm: 'h-3 w-3',
    md: 'h-4 w-4',
    lg: 'h-5 w-5'
  };

  return (
    <div className="flex items-start justify-between">
      <div className="flex-1 min-w-0">
        <label className="block text-sm font-medium text-secondary-900 cursor-pointer">{label}</label>
        {description && <p className="text-sm text-secondary-500 mt-1">{description}</p>}
      </div>
      <button
        type="button"
        onClick={() => onChange(!checked)}
        className={`${sizeClasses[size]} relative inline-flex flex-shrink-0 border-2 border-transparent rounded-full cursor-pointer transition-colors ease-in-out duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 ${
          checked ? 'bg-primary-600' : 'bg-secondary-200'
        }`}
      >
        <span
          className={`${dotSizeClasses[size]} pointer-events-none inline-block rounded-full bg-white shadow transform ring-0 transition ease-in-out duration-200 ${
            checked ? (size === 'sm' ? 'translate-x-4' : size === 'md' ? 'translate-x-5' : 'translate-x-6') : 'translate-x-0'
          }`}
        />
      </button>
    </div>
  );
};

export const Settings: React.FC = () => {
  const { settings, updateSettings, resetSettings, exportSettings, importSettings } = useSettings();
  const [activeTab, setActiveTab] = useState('connection');
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'error' } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const tabs = [
    { id: 'connection', label: 'Підключення', icon: '🔗' },
    { id: 'interface', label: 'Інтерфейс', icon: '🎨' },
    { id: 'monitoring', label: 'Моніторинг', icon: '📊' },
    { id: 'security', label: 'Безпека', icon: '🔒' },
    { id: 'export', label: 'Експорт', icon: '📤' },
  ];

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const handleExport = () => {
    const settingsData = exportSettings();
    const blob = new Blob([settingsData], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'tetracore-settings.json';
    a.click();
    URL.revokeObjectURL(url);
    showNotification('Налаштування експортовано успішно!');
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target?.result as string;
        if (importSettings(content)) {
          showNotification('Налаштування імпортовано успішно!');
        } else {
          showNotification('Помилка при імпорті налаштувань!', 'error');
        }
      };
      reader.readAsText(file);
    }
  };

  const handleReset = (category?: keyof typeof settings) => {
    if (window.confirm('Ви впевнені, що хочете скинути налаштування?')) {
      resetSettings(category);
      showNotification(category ? `Розділ скинуто!` : 'Всі налаштування скинуто!');
    }
  };

  const renderConnectionSettings = () => (
    <div className="space-y-6">
      <SettingCard title="WebSocket з'єднання" description="Налаштування основного з'єднання з сервером">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <ModernInput
            label="URL сервера"
            value={settings.connection.websocketUrl}
            onChange={(value) => updateSettings('connection', { websocketUrl: value })}
            type="url"
            placeholder="ws://localhost"
            icon="🌐"
          />
          <ModernInput
            label="Порт"
            value={settings.connection.websocketPort}
            onChange={(value) => updateSettings('connection', { websocketPort: value })}
            type="number"
            min={1}
            max={65535}
            icon="🔌"
          />
        </div>
      </SettingCard>

      <SettingCard title="API налаштування" description="Конфігурація REST API">
        <ModernInput
          label="API Endpoint"
          value={settings.connection.apiEndpoint}
          onChange={(value) => updateSettings('connection', { apiEndpoint: value })}
          type="url"
          placeholder="http://localhost:8000/api"
          icon="⚡"
        />
      </SettingCard>

      <SettingCard title="Таймаути і повтори" description="Налаштування надійності з'єднання">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <ModernInput
            label="Таймаут (мс)"
            value={settings.connection.connectionTimeout}
            onChange={(value) => updateSettings('connection', { connectionTimeout: value })}
            type="number"
            min={1000}
            max={30000}
            icon="⏱️"
          />
          <ModernInput
            label="Інтервал повтору (мс)"
            value={settings.connection.reconnectInterval}
            onChange={(value) => updateSettings('connection', { reconnectInterval: value })}
            type="number"
            min={1000}
            max={60000}
            icon="🔄"
          />
          <ModernInput
            label="Максимум спроб"
            value={settings.connection.maxReconnectAttempts}
            onChange={(value) => updateSettings('connection', { maxReconnectAttempts: value })}
            type="number"
            min={1}
            max={20}
            icon="🎯"
          />
        </div>
      </SettingCard>
    </div>
  );

  const renderInterfaceSettings = () => (
    <div className="space-y-6">
      <SettingCard title="Зовнішній вигляд" description="Персоналізація інтерфейсу">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <ModernSelect
            label="Тема"
            value={settings.ui.theme}
            onChange={(value) => updateSettings('ui', { theme: value })}
            options={[
              { value: 'light', label: '☀️ Світла' },
              { value: 'dark', label: '🌙 Темна' },
              { value: 'system', label: '🖥️ Системна' },
            ]}
            icon="🎨"
          />
          <ModernSelect
            label="Мова інтерфейсу"
            value={settings.ui.language}
            onChange={(value) => updateSettings('ui', { language: value })}
            options={[
              { value: 'uk', label: '🇺🇦 Українська' },
              { value: 'en', label: '🇺🇸 English' },
            ]}
            icon="🌍"
          />
        </div>
      </SettingCard>

      <SettingCard title="Формати відображення" description="Налаштування дати, часу та оновлень">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <ModernSelect
            label="Формат дати"
            value={settings.ui.dateFormat}
            onChange={(value) => updateSettings('ui', { dateFormat: value })}
            options={[
              { value: 'dd/mm/yyyy', label: 'ДД/ММ/РРРР' },
              { value: 'mm/dd/yyyy', label: 'ММ/ДД/РРРР' },
              { value: 'yyyy-mm-dd', label: 'РРРР-ММ-ДД' },
            ]}
            icon="📅"
          />
          <ModernSelect
            label="Формат часу"
            value={settings.ui.timeFormat}
            onChange={(value) => updateSettings('ui', { timeFormat: value })}
            options={[
              { value: '24h', label: '24-годинний' },
              { value: '12h', label: '12-годинний' },
            ]}
            icon="🕐"
          />
          <ModernInput
            label="Оновлення (мс)"
            value={settings.ui.refreshInterval}
            onChange={(value) => updateSettings('ui', { refreshInterval: value })}
            type="number"
            min={1000}
            max={60000}
            icon="🔄"
          />
        </div>
      </SettingCard>

      <SettingCard title="Режим відображення">
        <ModernToggle
          label="Компактний режим"
          description="Зменшує відступи і розміри елементів для економії місця"
          checked={settings.ui.compactMode}
          onChange={(checked) => updateSettings('ui', { compactMode: checked })}
        />
      </SettingCard>
    </div>
  );

  const renderMonitoringSettings = () => (
    <div className="space-y-6">
      <SettingCard title="Сповіщення" description="Налаштування системних повідомлень">
        <div className="space-y-4">
          <ModernToggle
            label="Увімкнути сповіщення"
            description="Отримувати повідомлення про події системи"
            checked={settings.monitoring.enableNotifications}
            onChange={(checked) => updateSettings('monitoring', { enableNotifications: checked })}
          />
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <ModernToggle
              label="Помилки"
              description="Сповіщати про помилки"
              checked={settings.monitoring.notifyOnErrors}
              onChange={(checked) => updateSettings('monitoring', { notifyOnErrors: checked })}
            />
            <ModernToggle
              label="Нові клієнти"
              description="Сповіщати про підключення"
              checked={settings.monitoring.notifyOnNewClients}
              onChange={(checked) => updateSettings('monitoring', { notifyOnNewClients: checked })}
            />
            <ModernToggle
              label="Відключення"
              description="Сповіщати про від'єднання"
              checked={settings.monitoring.notifyOnDisconnects}
              onChange={(checked) => updateSettings('monitoring', { notifyOnDisconnects: checked })}
            />
          </div>
        </div>
      </SettingCard>

      <SettingCard title="Логування" description="Налаштування системних логів">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <ModernSelect
            label="Рівень логування"
            value={settings.monitoring.logLevel}
            onChange={(value) => updateSettings('monitoring', { logLevel: value })}
            options={[
              { value: 'debug', label: '🐛 Debug' },
              { value: 'info', label: 'ℹ️ Info' },
              { value: 'warn', label: '⚠️ Warning' },
              { value: 'error', label: '❌ Error' },
            ]}
            icon="📝"
          />
          <ModernInput
            label="Максимум записів"
            value={settings.monitoring.maxLogEntries}
            onChange={(value) => updateSettings('monitoring', { maxLogEntries: value })}
            type="number"
            min={100}
            max={10000}
            icon="📊"
          />
        </div>
      </SettingCard>

      <SettingCard title="Метрики продуктивності" description="Моніторинг системних ресурсів">
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <ModernToggle
              label="Увімкнути метрики"
              description="Збирати дані про продуктивність"
              checked={settings.monitoring.enableMetrics}
              onChange={(checked) => updateSettings('monitoring', { enableMetrics: checked })}
            />
            <ModernInput
              label="Інтервал збору (мс)"
              value={settings.monitoring.metricsInterval}
              onChange={(value) => updateSettings('monitoring', { metricsInterval: value })}
              type="number"
              min={500}
              max={10000}
              icon="⏱️"
            />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <ModernToggle
              label="CPU"
              description="Моніторинг процесора"
              checked={settings.monitoring.showCpuUsage}
              onChange={(checked) => updateSettings('monitoring', { showCpuUsage: checked })}
            />
            <ModernToggle
              label="Пам'ять"
              description="Моніторинг RAM"
              checked={settings.monitoring.showMemoryUsage}
              onChange={(checked) => updateSettings('monitoring', { showMemoryUsage: checked })}
            />
            <ModernToggle
              label="Мережа"
              description="Мережевий трафік"
              checked={settings.monitoring.showNetworkUsage}
              onChange={(checked) => updateSettings('monitoring', { showNetworkUsage: checked })}
            />
          </div>
        </div>
      </SettingCard>
    </div>
  );

  const renderSecuritySettings = () => (
    <div className="space-y-6">
      <SettingCard title="Автентифікація" description="Налаштування доступу до системи">
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <ModernToggle
              label="Увімкнути автентифікацію"
              description="Вимагати логін для доступу"
              checked={settings.security.enableAuth}
              onChange={(checked) => updateSettings('security', { enableAuth: checked })}
            />
            <ModernInput
              label="Таймаут сесії (сек)"
              value={settings.security.sessionTimeout}
              onChange={(value) => updateSettings('security', { sessionTimeout: value })}
              type="number"
              min={300}
              max={86400}
              icon="⏰"
            />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <ModernToggle
              label="Двофакторна автентифікація"
              description="Додатковий рівень безпеки"
              checked={settings.security.requireTwoFactor}
              onChange={(checked) => updateSettings('security', { requireTwoFactor: checked })}
            />
            <ModernToggle
              label="Аудит лог"
              description="Логування дій користувачів"
              checked={settings.security.enableAuditLog}
              onChange={(checked) => updateSettings('security', { enableAuditLog: checked })}
            />
          </div>
        </div>
      </SettingCard>

      <SettingCard title="Політика паролів" description="Вимоги до безпеки паролів">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <ModernInput
            label="Мінімальна довжина"
            value={settings.security.passwordPolicy.minLength}
            onChange={(value) => updateSettings('security', { 
              passwordPolicy: { ...settings.security.passwordPolicy, minLength: value }
            })}
            type="number"
            min={4}
            max={50}
            icon="🔢"
          />
          <div className="space-y-3">
            <ModernToggle
              label="Великі літери"
              checked={settings.security.passwordPolicy.requireUppercase}
              onChange={(checked) => updateSettings('security', { 
                passwordPolicy: { ...settings.security.passwordPolicy, requireUppercase: checked }
              })}
              size="sm"
            />
            <ModernToggle
              label="Цифри"
              checked={settings.security.passwordPolicy.requireNumbers}
              onChange={(checked) => updateSettings('security', { 
                passwordPolicy: { ...settings.security.passwordPolicy, requireNumbers: checked }
              })}
              size="sm"
            />
            <ModernToggle
              label="Спеціальні символи"
              checked={settings.security.passwordPolicy.requireSymbols}
              onChange={(checked) => updateSettings('security', { 
                passwordPolicy: { ...settings.security.passwordPolicy, requireSymbols: checked }
              })}
              size="sm"
            />
          </div>
        </div>
      </SettingCard>

      <SettingCard title="Дозволені IP адреси" description="Контроль доступу за IP">
        <div className="space-y-3">
          {settings.security.allowedIPs.map((ip, index) => (
            <div key={index} className="flex items-center gap-3">
              <div className="flex-1">
                <ModernInput
                  label=""
                  value={ip}
                  onChange={(value) => {
                    const newIPs = [...settings.security.allowedIPs];
                    newIPs[index] = value as string;
                    updateSettings('security', { allowedIPs: newIPs });
                  }}
                  placeholder="192.168.1.1"
                  icon="🌐"
                />
              </div>
              <button
                onClick={() => {
                  const newIPs = settings.security.allowedIPs.filter((_, i) => i !== index);
                  updateSettings('security', { allowedIPs: newIPs });
                }}
                className="mt-6 px-4 py-2 bg-red-100 text-red-700 rounded-lg hover:bg-red-200 transition-colors duration-200"
              >
                🗑️
              </button>
            </div>
          ))}
          <button
            onClick={() => {
              const newIPs = [...settings.security.allowedIPs, ''];
              updateSettings('security', { allowedIPs: newIPs });
            }}
            className="w-full py-2 border-2 border-dashed border-secondary-300 rounded-lg text-secondary-500 hover:border-primary-300 hover:text-primary-600 transition-colors duration-200"
          >
            ➕ Додати IP адресу
          </button>
        </div>
      </SettingCard>
    </div>
  );

  const renderExportSettings = () => (
    <div className="space-y-6">
      <SettingCard title="Автоматичний експорт" description="Регулярне збереження даних">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <ModernToggle
            label="Увімкнути автоекспорт"
            description="Автоматично зберігати дані"
            checked={settings.export.autoExportLogs}
            onChange={(checked) => updateSettings('export', { autoExportLogs: checked })}
          />
          <ModernInput
            label="Максимальний розмір (MB)"
            value={settings.export.maxExportSize}
            onChange={(value) => updateSettings('export', { maxExportSize: value })}
            type="number"
            min={1}
            max={1000}
            icon="💾"
          />
        </div>
      </SettingCard>

      <SettingCard title="Формат і періодичність" description="Налаштування експорту">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <ModernSelect
            label="Формат файлу"
            value={settings.export.exportFormat}
            onChange={(value) => updateSettings('export', { exportFormat: value })}
            options={[
              { value: 'json', label: '📄 JSON' },
              { value: 'csv', label: '📊 CSV' },
              { value: 'xml', label: '📋 XML' },
            ]}
            icon="📁"
          />
          <ModernSelect
            label="Періодичність"
            value={settings.export.exportInterval}
            onChange={(value) => updateSettings('export', { exportInterval: value })}
            options={[
              { value: 'daily', label: '📅 Щодня' },
              { value: 'weekly', label: '📆 Щотижня' },
              { value: 'monthly', label: '🗓️ Щомісяця' },
            ]}
            icon="⏰"
          />
        </div>
      </SettingCard>

      <SettingCard title="Що експортувати" description="Вибір даних для збереження">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <ModernToggle
            label="Метрики"
            description="Дані продуктивності"
            checked={settings.export.includeMetrics}
            onChange={(checked) => updateSettings('export', { includeMetrics: checked })}
          />
          <ModernToggle
            label="Логи"
            description="Системні журнали"
            checked={settings.export.includeLogs}
            onChange={(checked) => updateSettings('export', { includeLogs: checked })}
          />
          <ModernToggle
            label="Дані клієнтів"
            description="Інформація про з'єднання"
            checked={settings.export.includeClientData}
            onChange={(checked) => updateSettings('export', { includeClientData: checked })}
          />
        </div>
      </SettingCard>
    </div>
  );

  const renderActiveTab = () => {
    switch (activeTab) {
      case 'connection': return renderConnectionSettings();
      case 'interface': return renderInterfaceSettings();
      case 'monitoring': return renderMonitoringSettings();
      case 'security': return renderSecuritySettings();
      case 'export': return renderExportSettings();
      default: return renderConnectionSettings();
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      {/* Header */}
      <div className="text-center py-8">
        <h1 className="text-4xl font-bold text-secondary-900 mb-3">
          ⚙️ Налаштування
        </h1>
        <p className="text-lg text-secondary-600">
          Персоналізуйте TetraCore StreamHub під свої потреби
        </p>
      </div>

      {/* Notification */}
      {notification && (
        <div className={`rounded-xl p-4 border-l-4 ${
          notification.type === 'success' 
            ? 'bg-green-50 border-green-400 text-green-800' 
            : 'bg-red-50 border-red-400 text-red-800'
        } animate-slideInFromTop`}>
          <div className="flex items-center">
            <span className="text-xl mr-3">
              {notification.type === 'success' ? '✅' : '❌'}
            </span>
            {notification.message}
          </div>
        </div>
      )}

      {/* Action Bar */}
      <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <h3 className="text-lg font-semibold text-secondary-900">
            🛠️ Управління налаштуваннями
          </h3>
          <div className="flex flex-wrap gap-3">
            <button
              onClick={handleExport}
              className="inline-flex items-center px-4 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors duration-200 shadow-sm hover:shadow-md"
            >
              <span className="mr-2">💾</span>
              Експорт
            </button>
            <button
              onClick={() => fileInputRef.current?.click()}
              className="inline-flex items-center px-4 py-2 bg-secondary-600 text-white rounded-lg hover:bg-secondary-700 transition-colors duration-200 shadow-sm hover:shadow-md"
            >
              <span className="mr-2">📁</span>
              Імпорт
            </button>
            <button
              onClick={() => handleReset()}
              className="inline-flex items-center px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors duration-200 shadow-sm hover:shadow-md"
            >
              <span className="mr-2">🔄</span>
              Скинути
            </button>
            <input
              ref={fileInputRef}
              type="file"
              accept=".json"
              onChange={handleImport}
              className="hidden"
            />
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-2">
        <div className="flex flex-wrap gap-2">
          {tabs.map(tab => (
            <TabButton
              key={tab.id}
              id={tab.id}
              label={tab.label}
              icon={tab.icon}
              isActive={activeTab === tab.id}
              onClick={() => setActiveTab(tab.id)}
            />
          ))}
        </div>
      </div>

      {/* Content */}
      <div className="min-h-[600px]">
        {renderActiveTab()}
      </div>

      {/* Reset Section Button */}
      <div className="text-center py-4">
        <button
          onClick={() => handleReset(activeTab as keyof typeof settings)}
          className="inline-flex items-center px-6 py-3 border-2 border-red-200 text-red-700 rounded-lg hover:bg-red-50 hover:border-red-300 transition-colors duration-200"
        >
          <span className="mr-2">🗑️</span>
          Скинути поточний розділ
        </button>
      </div>
    </div>
  );
};
